cW1C4WYqY6l4XWrG1v4fQWydwUnHCAA=
__BLONDIN_PAYLOAD__
EXPECTED_SHA=10c3ed1396aea8cb3749aa3bc8cd8d2824f478952bce5be347ad4e9f569191a8
ACTUAL_SHA="$(sha256sum "$TMP" | awk '{print $1}')"
[[ "$EXPECTED_SHA" == "$ACTUAL_SHA" ]] || { echo '[ERREUR] Integrite invalide.'; exit 1; }
bash -n "$TMP" || { echo '[ERREUR] Syntaxe invalide.'; exit 1; }
if [[ -f "$TARGET" ]]; then
  cp -p -- "$TARGET" "$BACKUP/gestionnaire-batocera.$(date +%Y%m%d-%H%M%S).bak"
fi
if [[ -f "$LAUNCHER" ]]; then
  cp -p -- "$LAUNCHER" "$BACKUP/lanceur-ports.$(date +%Y%m%d-%H%M%S).bak"
fi
install -m 755 "$TMP" "$TARGET"
cat > "$LAUNCHER" <<'__BLONDIN_LAUNCHER__'
#!/bin/bash
export DISPLAY="${DISPLAY:-:0}"
export BLONDIN_PORTS_PAD=1
SCRIPT=/userdata/system/gestionnaire-batocera.sh
if [[ ! -f "$SCRIPT" ]]; then
  echo '[ERREUR] Gestionnaire introuvable.'
  sleep 5
  exit 1
fi
# Fenetre centre approximativement sur DP-1 3440x1440 ;
# labwc peut ajuster le placement des fenetres XWayland.
exec xterm -bg black -fg white -fa 'DejaVu Sans Mono' -fs 32 \
  -geometry '100x29+650+85' -sb -rightbar -sl 5000 \
  -title 'Gestionnaire Batocera - BLONDIN EDITION' \
  -e /bin/bash "$SCRIPT"
__BLONDIN_LAUNCHER__
chmod 755 "$LAUNCHER"
echo '[OK] Gestionnaire v3.0.17 TEST installe.'
echo '[OK] Diagnostic pagine : Haut/Bas, Gauche/Droite.'
echo '[OK] Lanceur Ports en fenetre noire, position centrale demandee.'
echo '[OK] Configuration manette .keys conservee.'
echo "[INFO] Sauvegardes : $BACKUP"

echo '[INFO] Gestion > Gestionnaire dans Ports > Installer / réparer : illustrations GitHub.'

# Redémarrage ES différé après installation réussie, sans redémarrage de Batocera.
# Ne pas interrompre un jeu en cours ; la présence d'un émulateur est testée lorsque possible.
if command -v batocera-es-swissknife >/dev/null 2>&1; then
  emupid="$(batocera-es-swissknife --emupid 2>/dev/null || true)"
  if [[ -n "$emupid" && "$emupid" != 0 ]]; then
    echo '[INFO] Emulateur detecte : redemarrage automatique ES reporte.'
  elif pidof emulationstation >/dev/null 2>&1; then
    echo '[INFO] Actualisation automatique EmulationStation demandee.'
    ( sleep 2; batocera-es-swissknife --restart ) </dev/null >/tmp/gestionnaire-blondin-restart-es.log 2>&1 &
  else
    echo '[INFO] EmulationStation absent : aucun redemarrage necessaire.'
  fi
else
  echo '[ATTENTION] batocera-es-swissknife indisponible : actualisation manuelle necessaire.'
fi
